style.css:
body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
  
  /* Imagem de galáxia roxa e azul via Unsplash */
  background-image: url('https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?q=80&w=1920&auto=format&fit=crop');
  
  /* Garante que a imagem cubra toda a tela sem repetir */
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  background-attachment: fixed;
  
  /* Cor de fundo reserva caso a imagem demore para carregar */
  background-color: #0d0826;
}
